		expect(isIncompleteRule(filledInRule({ fieldKey: "" }))).toBe(true);
		expect(isIncompleteRule(filledInRule({ operator: "" }))).toBe(true);
		expect(isIncompleteRule(filledInRule({ value: "" }))).toBe(true);
